-- Transactional SQL fixture, no real payment, Auth session or Storage bytes.
begin;
create temporary table th_payment_results(stage text,result text) on commit drop;
create function pg_temp.th_pay_claims(uid uuid) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','aal','aal1')::text,true);end$$;
create function pg_temp.th_pay_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'PAYMENT ASSERT FAILED: %',label;end if;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
select ('94000000-7a21-4000-8000-'||lpad(n::text,12,'0'))::uuid,'payment-fixture-'||n||'@example.invalid',now(),jsonb_build_object('name','Payment fixture '||n) from generate_series(1,4)n;
do $$declare uid uuid;begin for uid in select id from auth.users where id::text like '94000000-7a21-%' loop perform pg_temp.th_pay_claims(uid);perform public.th_api('snapshot');end loop;end$$;
update public.th_shops set status='verified' where user_id in ('94000000-7a21-4000-8000-000000000001','94000000-7a21-4000-8000-000000000003');
do $$declare seller uuid:='94000000-7a21-4000-8000-000000000001';buyer uuid:='94000000-7a21-4000-8000-000000000002';seller2 uuid:='94000000-7a21-4000-8000-000000000003';outsider uuid:='94000000-7a21-4000-8000-000000000004';
 shop1 uuid;shop2 uuid;photo1 text;photo2 text;item1 uuid;item2 uuid;item3 uuid;oid uuid;expired_oid uuid;reply jsonb;sale jsonb;state jsonb;receipt text;begin
 select id into shop1 from public.th_shops where user_id=seller;select id into shop2 from public.th_shops where user_id=seller2;
 photo1:=seller::text||'/94000000-7a21-4000-8000-000000000099.png';photo2:=seller2::text||'/94000000-7a21-4000-8000-000000000099.png';
 insert into storage.objects(bucket_id,name,owner_id,metadata) values('product-photos',photo1,seller::text,'{"mimetype":"image/png","size":1024}'),('product-photos',photo2,seller2::text,'{"mimetype":"image/png","size":1024}');
 perform pg_temp.th_pay_claims(seller);perform public.th_api('upload_register',jsonb_build_object('path',photo1));
 perform pg_temp.th_pay_claims(seller2);perform public.th_api('upload_register',jsonb_build_object('path',photo2));
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode) values(shop1,'Payment item one','Payment fixture description','home','สภาพดี','Bangkok',photo1,150,'fixed') returning id into item1;
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode) values(shop2,'Private payment item two','Payment fixture description','home','สภาพดี','Bangkok',photo2,350,'fixed') returning id into item2;
 insert into public.th_products(shop_id,title,description,category,condition,location,image_path,price,mode) values(shop1,'Expiring item','Payment fixture description','home','สภาพดี','Bangkok',photo1,70,'fixed') returning id into item3;
 perform pg_temp.th_pay_claims(buyer);reply:=public.th_api('reserve',jsonb_build_object('productIds',jsonb_build_array(item1,item2),'requestKey','payment-multi-order-01','delivery','pickup'));oid:=(reply->>'orderId')::uuid;
 perform pg_temp.th_pay_assert((select payment_required from public.th_orders where id=oid),'new orders require simulated payment');
 state:=public.th_api('snapshot');perform pg_temp.th_pay_assert(state->'orderPayments'='true'::jsonb,'payment capability');
 reply:=public.th_api('order_messages',jsonb_build_object('orderId',oid,'shopId',shop1));perform pg_temp.th_pay_assert(reply->'canConfirm'='false'::jsonb,'unpaid buyer cannot confirm');
 begin perform public.th_api('order_handoff',jsonb_build_object('orderId',oid,'shopId',shop1));raise exception 'Unpaid handoff accepted';exception when sqlstate 'PT409' then null;end;
 perform pg_temp.th_pay_claims(seller);
 begin perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','payment-wrong-buyer-01'));raise exception 'Seller paid buyer order';exception when sqlstate 'PT404' then null;end;
 begin perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop1,'status','preparing'));raise exception 'Unpaid order prepared';exception when sqlstate 'PT409' then null;end;
 perform pg_temp.th_pay_claims(outsider);
 begin perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','payment-wrong-buyer-02'));raise exception 'Outsider paid order';exception when sqlstate 'PT404' then null;end;
 insert into pg_temp.th_payment_results values('Buyer ownership, unpaid pickup and fulfillment guard','PASS');
 perform pg_temp.th_pay_claims(buyer);
 update auth.users set email_confirmed_at=null where id=buyer;
 begin perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','payment-unconfirmed-01'));raise exception 'Unconfirmed email paid';exception when sqlstate 'PT403' then null;end;
 update auth.users set email_confirmed_at=now() where id=buyer;
 begin perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','bank_real','outcome','success','requestKey','payment-invalid-method'));raise exception 'Real payment accepted';exception when sqlstate 'PT400' then null;end;
 reply:=public.th_api('pay',jsonb_build_object('orderId',oid,'method','card_demo','outcome','declined','requestKey','payment-declined-01','amount',1));
 perform pg_temp.th_pay_assert(reply#>>'{payment,status}'='unpaid' and (reply#>>'{attempt,amount}')::int=500,'declined payment remains unpaid and uses stored total');
 perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','card_demo','outcome','declined','requestKey','payment-declined-01'));
 perform pg_temp.th_pay_assert((select count(*)=1 from public.th_order_payments where order_id=oid),'decline retry is idempotent');
 begin perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','payment-declined-01'));raise exception 'Request payload mismatch accepted';exception when sqlstate 'PT409' then null;end;
 reply:=public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','payment-success-01','amount',1,'userId',outsider));receipt:=reply#>>'{payment,reference}';
 perform pg_temp.th_pay_assert(reply#>>'{payment,status}'='paid_demo' and (reply#>>'{payment,amount}')::int=500 and reply#>'{payment,isDemo}'='true'::jsonb and left(receipt,5)='DEMO-','server total and explicit demo receipt');
 reply:=public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','payment-success-01'));perform pg_temp.th_pay_assert(reply#>>'{payment,reference}'=receipt,'success retry same receipt');
 begin perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','payment-success-02'));raise exception 'Second success accepted';exception when sqlstate 'PT409' then null;end;
 begin perform public.th_api('cancel',jsonb_build_object('orderId',oid));raise exception 'Paid order cancelled without refund';exception when sqlstate 'PT409' then null;end;
 update public.th_orders set expires_at=public.th_now()-1 where id=oid;perform public.th_settle();perform pg_temp.th_pay_assert((select status='reserved' and closed_at is null from public.th_orders where id=oid),'paid reservations never relist on deadline');
 state:=public.th_api('snapshot');select v into reply from jsonb_array_elements(state->'orders')x(v) where v->>'id'=oid::text;
 perform pg_temp.th_pay_assert(jsonb_array_length(reply->'paymentAttempts')=2 and reply#>>'{payment,reference}'=receipt,'buyer receives own history');
 insert into pg_temp.th_payment_results values('Decline, retries, server totals, unique demo receipt and paid reservation protection','PASS');
 perform pg_temp.th_pay_claims(seller);reply:=public.th_api('sales');select v into sale from jsonb_array_elements(reply->'sales')x(v) where v->>'id'=oid::text;
 perform pg_temp.th_pay_assert(sale->'paymentDemo'='true'::jsonb and sale#>>'{payment,status}'='paid_demo' and (sale->>'subtotal')::int=150,'seller sees own subtotal and demo status');
 perform pg_temp.th_pay_assert(position(receipt in sale::text)=0 and position('Private payment item two' in sale::text)=0 and not(sale->'payment'?'amount'),'seller cannot see receipt, global total or other shop items');
 begin perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop2,'status','preparing'));raise exception 'Other shop fulfillment accepted';exception when sqlstate 'PT404' then null;end;
 begin perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop1,'status','ready'));raise exception 'Ready before preparation accepted';exception when sqlstate 'PT409' then null;end;
 perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop1,'status','preparing'));reply:=public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop1,'status','ready'));
 perform pg_temp.th_pay_assert(reply#>>'{handoff,fulfillmentStatus}'='ready' and reply->'canConfirm'='true'::jsonb,'paid ready order allows handoff even after original deadline');
 perform public.th_api('order_handoff',jsonb_build_object('orderId',oid,'shopId',shop1));
 perform pg_temp.th_pay_claims(buyer);perform public.th_api('order_handoff',jsonb_build_object('orderId',oid,'shopId',shop1));perform pg_temp.th_pay_assert((select status='sold' from public.th_products where id=item1),'two party handoff sells first item');
 perform pg_temp.th_pay_claims(seller2);perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop2,'status','preparing'));perform public.th_api('fulfill',jsonb_build_object('orderId',oid,'shopId',shop2,'status','ready'));perform public.th_api('order_handoff',jsonb_build_object('orderId',oid,'shopId',shop2));
 perform pg_temp.th_pay_claims(buyer);reply:=public.th_api('order_handoff',jsonb_build_object('orderId',oid,'shopId',shop2));perform pg_temp.th_pay_assert(reply->>'orderStatus'='completed' and (select status='sold' from public.th_products where id=item2),'all shop handoffs finish real order');
 perform public.th_api('pay',jsonb_build_object('orderId',oid,'method','qr_demo','outcome','success','requestKey','payment-success-01'));
 insert into pg_temp.th_payment_results values('Seller privacy, preparation, ready and two party completion','PASS');
 reply:=public.th_api('reserve',jsonb_build_object('productIds',jsonb_build_array(item3),'requestKey','payment-expiry-order-01','delivery','pickup'));expired_oid:=(reply->>'orderId')::uuid;
 update public.th_orders set expires_at=public.th_now()-1 where id=expired_oid;
 begin perform public.th_api('pay',jsonb_build_object('orderId',expired_oid,'method','qr_demo','outcome','success','requestKey','payment-expired-01'));raise exception 'Expired order paid';exception when sqlstate 'PT409' then null;end;
 perform public.th_settle();perform pg_temp.th_pay_assert((select status='expired' from public.th_orders where id=expired_oid) and (select status='active' from public.th_products where id=item3),'unpaid expired order releases stock');
 perform pg_temp.th_pay_claims(outsider);state:=public.th_api('snapshot');perform pg_temp.th_pay_assert(position(receipt in state::text)=0,'other buyer cannot see receipt');
 perform set_config('request.jwt.claims','{}',true);state:=public.th_api('snapshot');perform pg_temp.th_pay_assert(position(receipt in state::text)=0,'public state contains no receipt');
 insert into pg_temp.th_payment_results values('Unpaid expiry and private buyer receipt isolation','PASS');
end$$;
set local role authenticated;
do $$begin
 begin perform 1 from public.th_order_payments;raise exception 'Direct payments readable';exception when insufficient_privilege then null;end;
 begin perform public.th_api_v3_base('snapshot');raise exception 'Previous dispatcher bypass exposed';exception when insufficient_privilege then null;end;
 begin perform public.th_snapshot_v3_base();raise exception 'Previous snapshot bypass exposed';exception when insufficient_privilege then null;end;
 begin perform public.th_payment('94000000-7a21-4000-8000-000000000001');raise exception 'Private payment helper exposed';exception when insufficient_privilege then null;end;
end$$;
reset role;
select stage,result from pg_temp.th_payment_results;
rollback;
